<script setup lang="ts">import {Head,Link,router} from '@inertiajs/vue3';import {ref} from 'vue';import PageContainer from '@/components/layout/PageContainer.vue';import PageHeader from '@/components/layout/PageHeader.vue';import {Button} from '@/components/ui/button';import {Input} from '@/components/ui/input';const props=defineProps<{boxes:any;filters:{search?:string}}>();const search=ref(props.filters.search??'');function apply(){router.get('/admin/message-boxes',{search:search.value},{preserveState:true,replace:true})}function remove(id:number){if(confirm('Delete this message box?'))router.delete(`/admin/message-boxes/${id}`)}</script>
<template><Head title="Message Boxes"/><PageContainer class="space-y-6"><PageHeader eyebrow="Content and Help" title="Message Boxes" description="Manage targeted popups, top banners, and bottom banners."><template #actions><Button as-child><Link href="/admin/message-boxes/create">Create Message Box</Link></Button></template></PageHeader><form class="flex gap-2" @submit.prevent="apply"><Input v-model="search" placeholder="Search message boxes..." class="max-w-md"/><Button type="submit" variant="outline">Search</Button></form><div class="overflow-hidden rounded-md border"><table class="w-full text-sm"><thead class="bg-muted/50 text-left"><tr><th class="p-3">Name / Title</th><th>Type</th><th>Audience</th><th>Priority</th><th>Status</th><th class="p-3 text-right">Actions</th></tr></thead><tbody><tr v-if="!boxes.data.length"><td colspan="6" class="p-8 text-center text-muted-foreground">No message boxes found.</td></tr><tr v-for="b in boxes.data" :key="b.id" class="border-t"><td class="p-3"><div class="font-medium">{{b.name}}</div><div class="text-muted-foreground">{{b.title}}</div></td><td>{{b.display_type.replace('_',' ')}}</td><td>{{b.audience}}</td><td>{{b.priority}}</td><td>{{b.is_active?'Active':'Inactive'}}</td><td class="p-3 text-right"><Button variant="ghost" as-child><Link :href="`/admin/message-boxes/${b.id}/edit`">Edit</Link></Button><Button variant="ghost" @click="remove(b.id)">Delete</Button></td></tr></tbody></table></div></PageContainer></template>
